 case 'transaction':path='/transactions'+(editing?'/'+record.id:'');method=editing?'patch':'post';keys=['notes','category_id','manual_classification',...(record.source==='provider'?[]:['payee','amount','direction','transaction_date']),...(editing?[]:['account_id','update_balance'])];break;
