}
const existingMode=ref('remaining'),pastSlots=ref<any[]>([]),pastError=ref(''),targetPreview=ref<any>();let detailTimer:ReturnType<typeof setTimeout>;
watch(()=>[existingMode.value,form.scheduled,form.balance,form.installment,form.frequency,form.first_date,form.day_one,form.day_two,form.category_id,form.month,form.scope],()=>{
 clearTimeout(detailTimer);
 detailTimer=setTimeout(async()=>{
  if(props.kind==='loan'&&!editing&&existingMode.value==='history'&&form.scheduled&&form.balance&&Number(form.installment)>0&&form.first_date){try{const q=new URLSearchParams({balance:form.balance,installment:form.installment,frequency:form.frequency,first_date:form.first_date,day_one:String(form.day_one),day_two:String(form.day_two)});const rows=(await json('/loans/preview?'+q)).payments;pastSlots.value=rows.filter((p:any)=>p.date<today).map((p:any)=>{const previous=pastSlots.value.find(old=>old.key===p.key);return {...p,paid:previous?.paid??true,actual_date:previous?.actual_date||p.date,amount:previous?.amount||dollars(p.amount_cents)};});pastError.value='';}catch{pastSlots.value=[];pastError.value='Enter valid loan terms to preview past installments.';}}
  if(props.kind==='target'&&form.category_id&&form.month){try{targetPreview.value=await json('/budget/targets/preview?'+new URLSearchParams({category_id:form.category_id,month:form.month}));}catch{targetPreview.value=null;}}
 },250);
},{immediate:true});
onBeforeUnmount(()=>clearTimeout(detailTimer));
watch(()=>form.due_day,(value)=>{if(props.kind!=='account'||editing)return;form.statement_enabled=Boolean(value);if(value){const date=new Date(today+'T12:00:00Z');const next=(offset:number)=>{const first=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()+offset,1,12));const last=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();first.setUTCDate(Math.min(Number(value),last));return first.toISOString().slice(0,10);};form.first_statement_date=next(0)>=today?next(0):next(1);}else form.first_statement_date=null;});
watch(()=>form.next_fee_date,(value)=>{if(props.kind==='account'&&!editing)form.fee_enabled=Boolean(value&&form.fee);});
