const accountSelection=computed(()=>props.kind==='schedule'&&form.kind==='income'||props.kind==='payment'||props.kind==='loan'&&form.scheduled);
const ordinaryAccounts=computed(()=>props.catalog?.accounts||[]);
const linkedMembers=computed(()=>(props.catalog?.members||[]).filter((m:any)=>m.user_id));const eligibleOwners=computed(()=>linkedMembers.value.filter((m:any)=>m.id!==page.props.household?.owner_member_id));
const financialPreview=ref<any>(),financialError=ref(''),previewLoading=ref(false),categoryUsage=ref<any>();let financialTimer:ReturnType<typeof setTimeout>;let financialRequest=0;
const financialValues=computed(()=>[form.amount,form.balance,form.repayment_total,form.installment,form.limit,form.account_id,form.direction,form.update_balance,form.scheduled,form.first_date,form.frequency,form.day_one,form.day_two,existingMode.value,pastSlots.value.filter(p=>p.paid).map(p=>[p.key,p.amount])]);
async function loadFinancialPreview(){const number=++financialRequest;financialPreview.value=undefined;financialError.value='';previewLoading.value=false;let kind=props.kind;const query=new URLSearchParams();
 if(kind==='transaction'&&!editing&&form.account_id&&form.amount&&!moneyError(form.amount)){query.set('account_id',form.account_id);query.set('amount',form.amount);query.set('direction',form.direction);query.set('update_balance',form.update_balance?'1':'0');}
 else if((kind==='limit'||kind==='account'&&form.type==='credit_card')&&form.limit&&!moneyError(form.limit)){kind='limit';query.set('limit',form.limit);query.set('balance',form.balance);if(editing)query.set('id',record.id);}
 else if(kind==='payment'&&form.amount&&!moneyError(form.amount,false,true)){query.set('id',props.endpoint?record.loan_id:record.id);query.set('amount',form.amount);if(props.endpoint)query.set('payment_id',record.id);}
 else if(kind==='loan'&&form.scheduled){const balance=editing&&record.series_id?form.repayment_total:form.balance;if(!balance||moneyError(balance)||moneyError(form.installment,false,true)||!form.first_date)return;query.set('balance',balance);query.set('installment',form.installment);query.set('frequency',form.frequency);query.set('first_date',form.first_date);query.set('day_one',String(form.day_one));query.set('day_two',String(form.day_two));if(editing)query.set('id',record.id);if(!editing&&existingMode.value==='history')pastSlots.value.filter(p=>p.paid).forEach((p,i)=>{query.set('past_payments['+i+'][slot_key]',p.key);query.set('past_payments['+i+'][amount]',p.amount);});}
