const deletionConsequences=computed(()=>{
 const endpoint=props.endpoint||'';
 if(endpoint==='/household')return ['Every member loses access immediately and returns to household setup.','Bank synchronizations and reminders stop.','The household’s records are retained without active member access.'];
 if(endpoint.startsWith('/household/members'))return ['This member loses sign-in access immediately.','Their assignments and financial history stay with the household.','Their pending reminders are canceled.'];
 if(endpoint.startsWith('/connections'))return ['This bank connection stops syncing.','Imported accounts, transactions, balances and payment attachments are retained.','You can continue using the household’s other accounts.'];
 if(endpoint.startsWith('/accounts'))return ['The account disappears from active accounts and transaction lists.','Its balance observations, transactions and change history are retained.','It is removed from paying-account selections and unpaid generated card bills stop.'];
 if(endpoint.startsWith('/loans/'))return ['The loan and its installments disappear from active views.','Recorded payment history is retained.','Its calendar reminders stop.'];
 if(endpoint.startsWith('/loan-payments'))return ['This recorded extra or past payment is removed.','The remaining balance increases and unpaid installments are recalculated.','The correction is recorded in change history.'];
 if(endpoint.startsWith('/categories'))return ['This category and its subcategories are removed.','Transactions, schedules and payments move to the replacement category.','Current and future targets on these categories are removed. Past targets remain historical.'];
 if(endpoint.startsWith('/transactions'))return ['This transaction disappears from active views and Budget.','Payment attachments become a deleted-transaction placeholder.','The account balance and payment status stay as recorded.'];
 if(record.kind==='subscription')return ['The subscription and all paid and unpaid payments are removed from active views.','Payment reminders stop.','Cancel subscription instead to preserve the paid payments in the subscription workspace.'];
 return ['The selected payment scope is removed from active views.','Its reminders stop and changes remain recorded in history.'];
});
