<template><div><Modal ref="modal" :open="true" :title="title" :subtitle="subtitle" :size="isNewMember?520:kind==='schedule'?800:kind==='loan'?720:600" :header-divider="!isNewMember" :class="{'member-editor':isNewMember}" :dirty="form.isDirty" :busy="form.processing" @close="emit('close')">
 <form ref="formElement" novalidate v-field-errors="form.errors" @focusout="blur" @submit.prevent="save"><div class="flex flex-col gap-5 px-6 py-6"><div v-if="Object.keys(form.errors).length" id="form-errors" tabindex="-1" role="alert" class="rounded-md border border-orange-200 bg-orange-50 p-3 text-orange-800"><p class="font-medium mb-2">Review these fields:</p><button v-for="(error,key) in form.errors" :key="key" type="button" class="block text-left underline" @click="focusField(String(key))">{{error}}</button></div><template v-if="isNewMember">
