  <p id="member-nickname-help" class="help mt-0.5">Shown on bills and records assigned to this person.</p>
 </div>
 <fieldset class="form-section p-4!">
  <legend>Sign-in</legend>
  <div class="flex flex-col gap-4">
   <div class="grid grid-cols-[18px_minmax(0,1fr)] gap-x-2.5 gap-y-3">
    <input id="member-google" v-model="form.sign_in" type="radio" name="member-sign-in" value="google" class="mt-0.5 size-[18px] accent-ink" aria-describedby="member-google-help"/>
    <div>
     <label for="member-google">Invite with a Google account</label>
     <p id="member-google-help" class="help mt-0.5">They can sign in, edit records and get reminders after accepting.</p>
    </div>
    <div v-if="form.sign_in==='google'" class="field col-start-2">
     <label for="edit-email">Google email</label>
     <input id="edit-email" v-model="form.email" type="email" required maxlength="200" autocomplete="email"/>
    </div>
   </div>
   <div class="grid grid-cols-[18px_minmax(0,1fr)] gap-x-2.5">
    <input id="member-no-login" v-model="form.sign_in" type="radio" name="member-sign-in" value="none" class="mt-0.5 size-[18px] accent-ink" aria-describedby="member-no-login-help"/>
    <div>
     <label for="member-no-login">No login for now</label>
     <p id="member-no-login-help" class="help mt-0.5">Use them for assigning bills. They can't sign in or get reminders until invited.</p>
    </div>
   </div>
