4"><h3 class="font-medium">Category path</h3><p class="mt-2">{{categoryPath}}</p><p v-if="editing&&categoryUsage" class="help mt-2">{{categoryUsage.transactions}} transactions · {{categoryUsage.schedules}} schedules · {{categoryUsage.payments}} payments use this category and its children.</p><p v-if="editing&&!record.parent_id&&form.parent_id&&categoryUsage" class="help mt-2 text-warning">{{categoryUsage.target_changes}} current or future target settings will be removed. Past targets stay historical.</p></section><template v-if="kind==='leave'"><p class="leading-relaxed text-muted">Leave {{record.name}}?</p><ul class="list-disc space-y-2 pl-5 text-muted"><li>You lose access immediately and return to household setup.</li><li>Your assignments and financial history stay with this household.</li><li>You can then create or join another household.</li></ul></template><template v-if="kind==='delete'"><p class="leading-relaxed text-muted">Review the consequences before removing this record. This cannot be undone through the app.</p><ul class="list-disc space-y-2 pl-5 text-muted"><li v-for="consequence in deletionConsequences" :key="consequence">{{consequence}}</li></ul><button v-if="record.kind==='subscription'&&!record.cancel_date" type="button" class="btn self-start" @click="emit('cancelSubscription',record)">Cancel subscription instead</button><p v-if="categoryUsage" class="help">{{categoryUsage.transactions}} transactions, {{categoryUsage.schedules}} schedules and {{categoryUsage.payments}} payments will move. {{categoryUsage.target_changes}} current or future target settings will be removed.</p><div v-if="endpoint?.startsWith('/schedules')&&record.kind!=='subscription'" class="field"><label for="remove-scope">Remove</label><SelectField id="remove-scope" v-model="form.scope" :options="[{value:'occurrence',label:'Only the selected payment'},{value:'future',label:'Selected and all future payments'}]"/></div><div v-if="endpoint?.startsWith('/categories')" class="field"><label for="edit-replacement-id">Replacement category</label><CategoryField id="edit-replacement-id" required v-model="form.replacement_id" :categories="catalog.categories.filter((c:any)=>c.kind===record.kind&&c.id!==record.id&&c.parent_id!==record.id)"/></div><div v-if="endpoint==='/household'" class="field"><label for="delete-household">Type the household name to confirm</label><input id="delete-household" v-model="form.name" required/><p class="help">Every member loses access immediately.</p></div></template> </div><div class="sticky bottom-0 z-10 flex flex-wrap items-center justify-between gap-3 border-t border-line bg-white px-6 py-4" :class="{'justify-end!':isNewMember}"><p v-if="!isNewMember" class="help">{{['delete','leave'].includes(kind)?'Review the consequences before confirming.':kind==='owner'?'Ownership changes immediately.':kind==='cancel'?'Cancel with the service separately.':'All fields are required unless marked Optional.'}}</p><div class="flex gap-2"><button type="button" class="btn" @click="close" :disabled="form.processing">Cancel</button><button :class="['delete','leave','cancel','owner'].includes(kind)?'btn-destructive':'btn-primary'" :disabled="form.processing"><LoaderCircle v-if="form.processing" :size="16" class="animate-spin"/>{{form.processing?'Saving…':form.hasErrors?'Try again':saveLabel}}</button></div></div></form>
